/**
 * THE MULTIVERSE — world/terrain.js
 * ==================================================================
 * THE VALLEY OF OMUN is generated by one deterministic height field, which
 * is also the game's collision model — the mesh is literally a sampling of
 * the field, so visuals and physics can never disagree.
 *
 * Anatomy of a sample:
 *   base       rolling continent-scale fBm
 *   basin      the valley itself (a broad, walkable trough)
 *   walls      sheer cliff bands from thresholded ridged noise
 *   terraces   quantised plateau country on the shoulders
 *   mountains  distant ranges that close the horizon
 *   rivers     carved along the minima of a second ridged field
 *   lakes      worley basins flooded below the water level
 *   coast      everything beyond the valley falls away into the ocean
 *
 * The field is pure maths (unit-tested); the streaming layer turns it into
 * LOD rings of merged chunk geometry that follow the player.
 */
import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Group,
  Mesh,
  MeshStandardMaterial,
} from 'three';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { NoiseStack } from '../core/noise.js';
import { clamp, clamp01, lerp, remap, smoothstep, smootherstep } from '../core/math.js';
import { Rng, hash2 } from '../core/rand.js';
import { patchTerrainMaterial } from '../render/shaders.js';
import { landmarkName } from '../lore.js';

