/* ------------------------------------------------------------------ *
 * The height field
 * ------------------------------------------------------------------ */

export class TerrainField {
  constructor(seed = 1337, options = {}) {
    this.seed = seed >>> 0;
    this.nz = new NoiseStack(this.seed);
    this.rng = new Rng(this.seed ^ 0x7e44);
    this.options = {
      valleyRadius: options.valleyRadius ?? 620, // walkable floor radius
      worldRadius: options.worldRadius ?? 4200,   // beyond this, ocean
      maxHeight: options.maxHeight ?? 420,
      minHeight: options.minHeight ?? -160,
      terraceHeight: options.terraceHeight ?? 22,
      waterLevel: options.waterLevel ?? WATER_LEVEL,
      lakeChance: options.lakeChance ?? 0.55,
      riverWidth: options.riverWidth ?? 42,
    };
    this._landmarks = null;
  }

  /* ---------------- large-scale shape ---------------- */

  /** Rolling base terrain: the "continent" before the valley is cut into it. */
  baseHeight(x, z) {
    const n = this.nz.fbm(x * 0.00042, z * 0.00042, { octaves: 5, frequency: 1, gain: 0.52 });
    const rolling = this.nz.fbm(x * 0.0016, z * 0.0016, { octaves: 4 });
    return n * 150 + rolling * 32;
  }

  /**
   * The ring of shoulders around the valley: zero on the flat floor, zero far
   * outside, one on the walls. Cliffs and terraces live on this band — putting
   * them anywhere else either paves the valley or levels the mountains.
   */
  rimBand(x, z) {
    const floorness = this.valleyShape(x, z);
    // Peaks at the midpoint between floor and outer country.
    return clamp01(4 * floorness * (1 - floorness));
  }

  /** The valley trough: a broad, softly-warped walkable basin. */
  valleyShape(x, z) {
    const warpX = this.nz.perlin.noise2(z * 0.0008, 11.3) * 220;
    const warpZ = this.nz.perlin.noise2(23.7, x * 0.0008) * 220;
    const cx = x + warpX;
    const cz = z + warpZ;
    const radius = this.options.valleyRadius * (1 + this.nz.perlin.noise2(cx * 0.0012, cz * 0.0012) * 0.28);
    const d = Math.hypot(cx, cz);
    // Flat-ish floor, then a quick rise into the shoulders.
    const floor = 1 - smoothstep(radius * 0.55, radius, d);
    return floor;
  }

  /** Sheer cliff bands: the "gigantic cliffs" of the valley walls. */
  cliffWalls(x, z, rim) {
    if (rim < 0.02) return 0;
    const ridge = this.nz.ridged(x * 0.0011, z * 0.0011, { octaves: 5, sharpness: 1.3 });
    // Threshold into narrow bands: this is what makes walls, not slopes.
    const band = smoothstep(0.46, 0.62, ridge);
    const band2 = smoothstep(0.68, 0.78, ridge);
    const height = band * 130 + band2 * 165;
    const variety = 0.6 + this.nz.fbm(x * 0.004, z * 0.004, { octaves: 3 }) * 0.35 + 0.2;
    return height * rim * variety;
  }

  /** Terraced plateau country — quantised steps facing the valley. */
  terraces(x, z, rim) {
    if (rim < 0.05) return 0;
    const ridge = this.nz.ridged(x * 0.0009 + 100, z * 0.0009 - 40, { octaves: 4 });
    const terraceAmount = smoothstep(0.45, 0.72, ridge) * rim;
    if (terraceAmount < 0.01) return 0;
    const h = this.nz.fbm(x * 0.0022, z * 0.0022, { octaves: 4 }) * 120 + 60;
    const step = this.options.terraceHeight;
    const stepped = Math.floor(h / step) * step;
    const frac = (h - stepped) / step;
    const smoothed = stepped + smootherstep(frac * 1.35 - 0.175) * step;
    return (smoothed - h) * terraceAmount * 1.15;
  }

  /** Distant mountain ranges closing the horizon. */
  mountains(x, z, floorness) {
    const d = Math.hypot(x, z);
    const rangeFade = smoothstep(this.options.valleyRadius * 1.15, this.options.worldRadius * 0.62, d);
    if (rangeFade < 0.01) return 0;
    const ridge = this.nz.ridged(x * 0.00058, z * 0.00058, { octaves: 6, sharpness: 1.1 });
    const peaks = Math.pow(ridge, 1.6);
    const massif = this.nz.fbm(x * 0.0003 + 77, z * 0.0003 + 12, { octaves: 3 }) * 0.5 + 0.5;
    return peaks * 520 * rangeFade * (0.45 + massif * 0.9) * (1 - floorness * 0.98);
  }

  /**
   * Rivers carved along the minima of a ridged field. A river is not a dent:
   * its bed is pinned below the water level so the channel actually holds
   * water, and so the places where it crosses a rim become waterfalls.
   */
  riverCarve(x, z, floorness, h) {
    // A river is a contour line of a smooth field, not a hole punched in a
    // threshold: this is what makes them meander instead of cross-hatching.
    const d = Math.abs(this.nz.fbm(x * 0.0021 + 41.7, z * 0.0021 - 17.3, { octaves: 3 }));
    const half = (this.options.riverWidth / 2600) * (0.75 + floorness * 0.85);
    const bank = half * 2.6;
    if (d > bank) return h;
    const t = smoothstep(bank, half * 0.6, d);
    const bed = -4.5 - floorness * 2 - (this.nz.fbm(x * 0.004, z * 0.004, { octaves: 2 }) * 0.5 + 0.5) * 4;
    return lerp(h, Math.min(h, bed), t);
  }

  /** Worley lake basins, flooded below the water level. Sparse want. */
  lakeBasin(x, z, base, floorness) {
    const chance = this.options.lakeChance * (0.18 + floorness * 0.95);
    if (chance < 0.06 || base < 3) return 0;
    const cell = this.nz.worley(x * 0.0016, z * 0.0016, 17);
    const basin = smoothstep(0.56, 0.06, cell.f1);
    if (basin < 0.05) return 0;
    const depth = basin * 19 * chance;
    const rim = smoothstep(0.24, 0.9, cell.f1) * 9;
    return (-depth + rim * basin) * (0.4 + floorness * 0.85);
  }

  /** Ocean: the world falls away past the coast. */
  oceanFalloff(x, z) {
    const d = Math.hypot(x, z);
    const coast = smoothstep(this.options.worldRadius * 0.62, this.options.worldRadius * 1.05, d);
    return -coast * 220;
  }

  /* ---------------- the composed field ---------------- */

  heightAt(x, z) {
    const floorness = this.valleyShape(x, z);
    const rim = this.rimBand(x, z);
    // The floor of the valley: walkable, lush, comfortably above the water.
    const floor =
      19 +
      this.nz.fbm(x * 0.0026, z * 0.0026, { octaves: 3 }) * 8.5 +
      this.nz.fbm(x * 0.013, z * 0.013, { octaves: 2 }) * 1.8;
    // Inside the valley the shoulders are held above the waterline, so the
    // only things below the water are the rivers and the lakes that are meant
    // to be there.
    let base = this.baseHeight(x, z);
    if (floorness > 0.12) base = Math.max(base, -10 - 34 * (1 - floorness));
    let h = lerp(base, floor, floorness * 0.95);
    h += this.cliffWalls(x, z, rim);
    h += this.terraces(x, z, rim);
    h += this.mountains(x, z, floorness);
    h += this.lakeBasin(x, z, h, floorness);
    h = this.riverCarve(x, z, floorness, h);
    h += this.oceanFalloff(x, z);
    // A little high-frequency roughness in the cliff country only, so the
    // floor stays smooth to run across.
    const rough = rim * 4.5 + (1 - floorness) * 2.4 + 0.7;
    h += this.nz.fbm(x * 0.02, z * 0.02, { octaves: 3 }) * rough;
    return clamp(h, this.options.minHeight, this.options.maxHeight);
  }

  /** Approximate surface normal via central differences. */
  normalAt(x, z, out = { x: 0, y: 1, z: 0 }, eps = 1.4) {
    const hL = this.heightAt(x - eps, z);
    const hR = this.heightAt(x + eps, z);
    const hD = this.heightAt(x, z - eps);
    const hU = this.heightAt(x, z + eps);
    const nx = hL - hR;
    const nz = hD - hU;
    const ny = 2 * eps;
    const len = Math.hypot(nx, ny, nz) || 1;
    out.x = nx / len;
    out.y = ny / len;
    out.z = nz / len;
    return out;
  }

  slopeAt(x, z) {
    const n = this.normalAt(x, z, { x: 0, y: 1, z: 0 });
    return 1 - clamp01(n.y);
  }

  isWater(x, z) {
    return this.heightAt(x, z) < this.options.waterLevel - 0.15;
  }

  depthAt(x, z) {
    return Math.max(0, this.options.waterLevel - this.heightAt(x, z));
  }

  /** Distance to the nearest coastline (negative when underwater). */
  shoreDistance(x, z, samples = 6, step = 12) {
    const base = this.heightAt(x, z) - this.options.waterLevel;
    if (base > 0) return base;
    let best = 0;
    for (let i = 1; i <= samples; i++) {
      let found = false;
      for (let a = 0; a < 8; a++) {
        const angle = (a / 8) * Math.PI * 2;
        const px = x + Math.cos(angle) * step * i;
        const pz = z + Math.sin(angle) * step * i;
        if (this.heightAt(px, pz) > this.options.waterLevel) {
          found = true;
          break;
        }
      }
      if (found) {
        best = -step * i;
        break;
      }
      best = -step * (i + 1);
    }
    return best;
  }

  /* ---------------- biomes ---------------- */

  /**
   * Biome weights at a point. Weight order matches BIOME_LIST.indices:
   * [primary, secondary, tertiary, quaternary] surfaces.
   */
  biomeAt(x, z) {
    const h = this.heightAt(x, z);
    const slope = this.slopeAt(x, z);
    const moisture = clamp01(this.nz.fbm(x * 0.0009 + 300, z * 0.0009 - 120, { octaves: 3 }) * 0.5 + 0.5);
    const warmth = clamp01(
      0.55 + this.nz.fbm(x * 0.00042 - 900, z * 0.00042 + 400, { octaves: 2 }) * 0.4 - clamp01(h / 420) * 0.55
    );
    const nearWater = h < 8 ? 1 : clamp01(1 - (h - 8) / 22);
    const valley = this.valleyShape(x, z);

    let biome;
    if (h < 1.5) biome = nearWater > 0.35 ? BIOMES.wetland : BIOMES.beach;
    else if (h < 6) biome = BIOMES.beach;
    else if (h < 9.5 && moisture > 0.55) biome = BIOMES.wetland;
    else if (h > 300) biome = BIOMES.alpine;
    else if (h > 210) biome = BIOMES.highland;
    else if (slope > 0.52) biome = BIOMES.cliff;
    else if (warmth > 0.62 && moisture > 0.58) biome = BIOMES.jungle;
    else if (moisture > 0.5 && h < 90) biome = BIOMES.forest;
    else if (moisture < 0.3 && h > 60 && slope < 0.3) biome = BIOMES.crystal;
    else if (valley < 0.3 && slope > 0.42) biome = BIOMES.abyssRim;
    else biome = BIOMES.meadow;

    // Blend neighbours by proximity to the thresholds so transitions are soft.
    const weightFloor = clamp01(1 - slope * 0.6);
    return {
      biome,
      moisture,
      warmth,
      slope,
      height: h,
      weightBits: [1 - weightFloor * 0.5, weightFloor * 0.3, slope * 0.2, clamp01(h / 420) * 0.15],
    };
  }

  /** Surface-kind weights (for the splat shader) at a point. */
  surfaceWeights(x, z, out = [1, 0, 0, 0]) {
    const { biome, slope, height } = this.biomeAt(x, z);
    const h = height;
    const w0 = clamp01(1 - slope * 1.4) * clamp01(1 - clamp01((h - 120) / 220));
    const w1 = clamp01(slope * 1.7);
    const w2 = clamp01(1 - Math.abs(h - 12) / 26) * (1 - slope);
    const w3 = clamp01((h - 200) / 180) * clamp01(1 - slope * 0.4);
    const sum = w0 + w1 + w2 + w3 || 1;
    out[0] = w0 / sum;
    out[1] = w1 / sum;
    out[2] = w2 / sum;
    out[3] = w3 / sum;
    out.biome = biome;
    return out;
  }

  /* ---------------- landmarks (named places) ---------------- */

  /**
   * Deterministically place named landmarks: the tallest peaks, the biggest
   * waterfalls and the deepest lakes. Names come from lore.landmarkName().
   */
  landmarks(count = 14) {
    if (this._landmarks) return this._landmarks;
    const rng = new Rng(this.seed ^ 0x1a4d);
    const found = [];
    let attempts = 0;
    const maxAttempts = count * 260;
    while (found.length < count && attempts < maxAttempts) {
      attempts++;
      const angle = rng.angle();
      const radius = lerp(this.options.valleyRadius * 0.18, this.options.worldRadius * 0.72, Math.sqrt(rng.float()));
      const x = Math.cos(angle) * radius;
      const z = Math.sin(angle) * radius;
      const h = this.heightAt(x, z);
      const slope = this.slopeAt(x, z);
      const isPeak = h > 180 && slope < 0.6;
      const isCliff = slope > 0.62 && h > 60;
      const isLake = h < -4 && h > -60;
      if (!isPeak && !isCliff && !isLake) continue;
      // Keep landmarks apart.
      if (found.some((l) => Math.hypot(l.x - x, l.z - z) < 260)) continue;
      const kind = isPeak ? 'peak' : isCliff ? 'waterfall' : 'lake';
      const id = hash2(Math.round(x), Math.round(z));
      found.push({
        id,
        kind,
        x,
        z,
        height: h,
        slope,
        name: landmarkName(id),
        shortName: landmarkName(id, { article: false }),
        discovered: false,
      });
    }
    this._landmarks = found;
    return found;
  }

  /** Neighbouring peaks, for the horizon silhouette list. */
  nearestLandmark(x, z) {
    let best = null;
    let bestD = Infinity;
    for (const landmark of this.landmarks()) {
      const d = (landmark.x - x) ** 2 + (landmark.z - z) ** 2;
      if (d < bestD) {
        bestD = d;
        best = landmark;
      }
    }
    return best ? { landmark: best, distance: Math.sqrt(bestD) } : null;
  }
}

/* ------------------------------------------------------------------ *
 * Streaming terrain meshes
 * ------------------------------------------------------------------ */

const LOD_RINGS = [
  { resolution: 64, segments: 48 },
  { resolution: 40, segments: 24 },
  { resolution: 22, segments: 12 },
  { resolution: 14, segments: 6 },
];

/**
 * Builds a chunk's geometry by sampling the field. Vertex attributes:
 *   position, normal, uv, aWeights (4 biome surface weights), color (tint)
 */
export function buildChunkGeometry(field, chunkX, chunkZ, chunkSize, segments) {
  const geometry = new BufferGeometry();
  const verts = (segments + 1) * (segments + 1);
  const positions = new Float32Array(verts * 3);
  const normals = new Float32Array(verts * 3);
  const uvs = new Float32Array(verts * 2);
  const weights = new Float32Array(verts * 4);
  const colors = new Float32Array(verts * 3);
  const indices = new Uint32Array(segments * segments * 6);

  const originX = chunkX * chunkSize;
  const originZ = chunkZ * chunkSize;
  const step = chunkSize / segments;
  const tmp = [0, 0, 0, 0];
  let vi = 0;

  for (let j = 0; j <= segments; j++) {
    for (let i = 0; i <= segments; i++) {
      const x = originX + i * step;
      const z = originZ + j * step;
      const y = field.heightAt(x, z);
      const n = field.normalAt(x, z, { x: 0, y: 1, z: 0 }, Math.max(0.6, step * 0.35));
      field.surfaceWeights(x, z, tmp);
      const biome = tmp.biome;

      positions[vi * 3] = i * step;
      positions[vi * 3 + 1] = y;
      positions[vi * 3 + 2] = j * step;
      normals[vi * 3] = n.x;
      normals[vi * 3 + 1] = n.y;
      normals[vi * 3 + 2] = n.z;
      uvs[vi * 2] = x / 12;
      uvs[vi * 2 + 1] = z / 12;
      weights[vi * 4] = tmp[0];
      weights[vi * 4 + 1] = tmp[1];
      weights[vi * 4 + 2] = tmp[2];
      weights[vi * 4 + 3] = tmp[3];

      const tint = biome.ground;
      const r = ((tint >> 16) & 255) / 255;
      const g = ((tint >> 8) & 255) / 255;
      const b = (tint & 255) / 255;
      // Macro tint varies gently; the shader also applies its own macro noise.
      const variation = 0.9 + hash2(Math.round(x), Math.round(z)) % 1000 / 5000;
      colors[vi * 3] = lerp(1, r * 1.6, 0.22) * variation;
      colors[vi * 3 + 1] = lerp(1, g * 1.6, 0.22) * variation;
      colors[vi * 3 + 2] = lerp(1, b * 1.6, 0.22) * variation;
      vi++;
    }
  }

  let ii = 0;
  for (let j = 0; j < segments; j++) {
    for (let i = 0; i < segments; i++) {
      const a = j * (segments + 1) + i;
      const b = a + 1;
      const c = a + segments + 1;
      const d = c + 1;
      indices[ii++] = a;
      indices[ii++] = c;
      indices[ii++] = b;
      indices[ii++] = b;
      indices[ii++] = c;
      indices[ii++] = d;
    }
  }

  geometry.setAttribute('position', new BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new BufferAttribute(normals, 3));
  geometry.setAttribute('uv', new BufferAttribute(uvs, 2));
  geometry.setAttribute('aWeights', new BufferAttribute(weights, 4));
  geometry.setAttribute('color', new BufferAttribute(colors, 3));
  geometry.setIndex(new BufferAttribute(indices, 1));
  geometry.computeBoundingSphere();
  return geometry;
}

/**
 * Streaming terrain: LOD rings of merged chunk meshes that follow the player.
 * Only the ring the player crossed is rebuilt, and only when they cross a
 * chunk boundary — the valley never hitches.
 */
export class TerrainStreamer {
  constructor({ scene, field, textures, quality, seed = 1337 }) {
    this.scene = scene;
    this.field = field;
    this.textures = textures;
    this.quality = quality;
    this.chunkSize = quality.terrainChunkSize ?? 128;
    this.radius = clamp(quality.terrainRadius ?? 6, 1, 14);
    this.group = new Group();
    this.group.name = 'terrain';
    this.scene.add(this.group);

    this.surfaces = [
      textures.surface('grass', { seed: seed + 1 }),
      textures.surface('rock', { seed: seed + 2 }),
      textures.surface('sand', { seed: seed + 3 }),
      textures.surface('snow', { seed: seed + 4 }),
    ];
    this.material = new MeshStandardMaterial({
      map: this.surfaces[0].map,
      normalMap: this.surfaces[0].normalMap,
      roughnessMap: this.surfaces[0].roughnessMap,
      vertexColors: true,
      metalness: 0.02,
      roughness: 0.94,
      envMapIntensity: 0.55,
      dithering: true,
    });
    this.surfaceUniforms = patchTerrainMaterial(this.material, this.surfaces, {
      macroScale: 0.0032,
      detailFade: quality.terrainDetailFade ?? 240,
      repeat0: 42,
      repeat1: 22,
      repeat2: 34,
      repeat3: 28,
    });

    this.rings = LOD_RINGS.map(() => ({ meshes: [], built: false, centre: { x: null, z: null } }));
    this.lastCentre = { x: null, z: null };
    this.chunksBuilt = 0;
    this.triangles = 0;
  }

  /** Ring index for a chunk offset from the player. */
  ringFor(dx, dz) {
    const d = Math.max(Math.abs(dx), Math.abs(dz));
    if (d <= 0) return 0;
    if (d <= 1) return 0;
    if (d <= 2) return 1;
    if (d <= 4) return 2;
    return 3;
  }

  /** Rebuild rings whose centre chunk changed. */
  update(playerPosition, { force = false } = {}) {
    const cx = Math.floor(playerPosition.x / this.chunkSize);
    const cz = Math.floor(playerPosition.z / this.chunkSize);
    if (!force && cx === this.lastCentre.x && cz === this.lastCentre.z) return false;
    this.lastCentre = { x: cx, z: cz };

    const buckets = LOD_RINGS.map(() => []);
    for (let dz = -this.radius; dz <= this.radius; dz++) {
      for (let dx = -this.radius; dx <= this.radius; dx++) {
        const ring = this.ringFor(dx, dz);
        if (Math.max(Math.abs(dx), Math.abs(dz)) > this.radius) continue;
        buckets[ring].push([cx + dx, cz + dz]);
      }
    }

    for (let r = 0; r < LOD_RINGS.length; r++) {
      const ring = this.rings[r];
      const changed =
        force ||
        bucketChanged(
          ring.centre.x,
          ring.centre.z,
          buckets[r],
          r === 0 ? 1 : r === 1 ? 1 : r === 2 ? 2 : 4
        );
      if (!changed) continue;
      this.rebuildRing(r, buckets[r]);
      ring.centre = { x: cx, z: cz };
    }
    return true;
  }

  rebuildRing(ringIndex, chunkCoords) {
    const ring = this.rings[ringIndex];
    const spec = LOD_RINGS[ringIndex];
    // Dispose previous merged mesh
    for (const mesh of ring.meshes) {
      this.group.remove(mesh);
      mesh.geometry.dispose();
    }
    ring.meshes = [];
    if (chunkCoords.length === 0) return;

    const geometries = [];
    for (const [chunkX, chunkZ] of chunkCoords) {
      const geometry = buildChunkGeometry(this.field, chunkX, chunkZ, this.chunkSize, spec.segments);
      geometry.translate(chunkX * this.chunkSize, 0, chunkZ * this.chunkSize);
      geometries.push(geometry);
    }
    const merged = BufferGeometryUtils.mergeGeometries(geometries, false);
    for (const g of geometries) g.dispose();
    if (!merged) return;
    merged.computeBoundingSphere();
    const mesh = new Mesh(merged, this.material);
    mesh.name = `terrain-ring-${ringIndex}`;
    mesh.castShadow = ringIndex <= 1;
    mesh.receiveShadow = true;
    mesh.matrixAutoUpdate = false;
    mesh.updateMatrix();
    mesh.frustumCulled = true;
    this.group.add(mesh);
    ring.meshes.push(mesh);
    this.chunksBuilt += chunkCoords.length;
    this.triangles += merged.index ? merged.index.count / 3 : 0;
  }

  /** Called every frame for shader animation (wetness, wind). */
  updateUniforms(dt, { wetness = 0, time = 0 } = {}) {
    this.surfaceUniforms.uTime.value = time;
    this.surfaceUniforms.uWetness.value = lerp(this.surfaceUniforms.uWetness.value, wetness, clamp01(dt * 2));
  }

  /** Draw a top-down minimap of the loaded region. */
  sampleGrid(size = 64, spacing = 64, centre = { x: 0, z: 0 }) {
    const grid = new Float32Array(size * size);
    const half = (size - 1) / 2;
    for (let j = 0; j < size; j++) {
      for (let i = 0; i < size; i++) {
        const x = centre.x + (i - half) * spacing;
        const z = centre.z + (j - half) * spacing;
        grid[j * size + i] = this.field.heightAt(x, z);
      }
    }
    return grid;
  }

  dispose() {
    for (const ring of this.rings) {
      for (const mesh of ring.meshes) {
        this.group.remove(mesh);
        mesh.geometry.dispose();
      }
      ring.meshes = [];
    }
    this.material.dispose();
    this.scene.remove(this.group);
  }
}

function bucketChanged(prevX, prevZ, coords, threshold) {
  if (prevX === null || prevZ === null) return true;
  for (const [x, z] of coords) {
    if (Math.abs(x - prevX) >= threshold || Math.abs(z - prevZ) >= threshold) return true;
  }
  return false;
}

/** A convenience wrapper that owns the field and its streamer. */
export class ValleyTerrain {
  constructor({ scene, textures, quality, seed = 1337, options = {} }) {
    this.field = new TerrainField(seed, options);
    this.streamer = new TerrainStreamer({ scene, field: this.field, textures, quality, seed });
    this.landmarks = this.field.landmarks();
  }

  heightAt(x, z) {
    return this.field.heightAt(x, z);
  }
  normalAt(x, z, out) {
    return this.field.normalAt(x, z, out);
  }
  isWater(x, z) {
    return this.field.isWater(x, z);
  }
  update(playerPosition, dt, extras) {
    this.streamer.update(playerPosition);
    this.streamer.updateUniforms(dt, extras);
  }
  dispose() {
    this.streamer.dispose();
  }
}
